-- Remove indexes duplicated by the pre-existing owner/user indexes.
drop index if exists public.shift_group_members_user_group_idx;
drop index if exists public.shift_group_sharing_settings_owner_group_idx;
drop index if exists public.shift_group_sharing_exceptions_owner_group_idx;
create index if not exists shift_group_invitations_invited_by_idx on public.shift_group_invitations(invited_by);
create index if not exists shift_group_sharing_exceptions_group_owner_idx on public.shift_group_sharing_exceptions(group_id, owner_id);
create index if not exists shift_group_sharing_exceptions_shift_idx on public.shift_group_sharing_exceptions(shift_id);
create index if not exists shift_groups_created_by_idx on public.shift_groups(created_by);
create index if not exists shift_sharing_exceptions_shift_idx on public.shift_sharing_exceptions(shift_id);
drop policy if exists "Users can view own work sites" on public.work_sites;
drop policy if exists "Users can insert own work sites" on public.work_sites;
drop policy if exists "Users can update own work sites" on public.work_sites;
drop policy if exists "Users can delete own work sites" on public.work_sites;
create policy "Users can view own work sites" on public.work_sites for select to authenticated using (user_id = (select auth.uid()));
create policy "Users can insert own work sites" on public.work_sites for insert to authenticated with check (user_id = (select auth.uid()));
create policy "Users can update own work sites" on public.work_sites for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "Users can delete own work sites" on public.work_sites for delete to authenticated using (user_id = (select auth.uid()));
drop policy if exists "Users can view own shift templates" on public.shift_templates;
drop policy if exists "Users can insert own shift templates" on public.shift_templates;
drop policy if exists "Users can update own shift templates" on public.shift_templates;
drop policy if exists "Users can delete own shift templates" on public.shift_templates;
create policy "Users can view own shift templates" on public.shift_templates for select to authenticated using (user_id = (select auth.uid()));
create policy "Users can insert own shift templates" on public.shift_templates for insert to authenticated with check (user_id = (select auth.uid()) and (site_id is null or exists (select 1 from public.work_sites s where s.id = shift_templates.site_id and s.user_id = (select auth.uid()))));
create policy "Users can update own shift templates" on public.shift_templates for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()) and (site_id is null or exists (select 1 from public.work_sites s where s.id = shift_templates.site_id and s.user_id = (select auth.uid()))));
create policy "Users can delete own shift templates" on public.shift_templates for delete to authenticated using (user_id = (select auth.uid()));
drop policy if exists "Owners manage own sharing settings" on public.shift_sharing_settings;
create policy "Owners manage own sharing settings" on public.shift_sharing_settings for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
drop policy if exists "Owners manage sharing user rules" on public.shift_sharing_users;
create policy "Owners manage sharing user rules" on public.shift_sharing_users for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
drop policy if exists "Owners manage sharing exceptions" on public.shift_sharing_exceptions;
create policy "Owners manage sharing exceptions" on public.shift_sharing_exceptions for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
alter function public.get_shared_shifts(date,date) set search_path = '';
